  const headhuntersDropdown = document.getElementById("headhuntersDropdown");
  const headhuntersSearch = document.getElementById("headhuntersSearch");
  const searchableContainer = document.querySelector(".searchable-dropdown-container");
  const positionsDropdown = document.getElementById("positionsDropdown");
  const positionsSearch = document.getElementById("positionsSearch");

  const copyButton = document.getElementById("Copy");

  const saveSessionButton = document.getElementById("save-filter-session");
  const jsonInput = document.getElementById("jsonFile");
  const uploadBtn = document.getElementById("uploadBtn");
  const toggleButton = document.getElementById("toggleButton");
  const collapsibleContent = document.getElementById("collapsibleContent");

  // 更新猎头信息函数
  async function refreshHeadhunterData() {
    try {
      console.log("开始更新猎头信息...");

      // 禁用按钮并显示加载状态
      refreshHeadhunterButton.disabled = true;
      refreshHeadhunterButton.textContent = "更新中...";

      // 显示加载状态
      headhuntersDropdown.innerHTML = "<option>加载中...</option>";

      // 获取猎头数据
      const headhuntersResponses = await Promise.all([
        fetch("https://talent.example.invalid/api/get_headhunters.php", {
          method: "POST",
          body: new URLSearchParams({
            headhunters: "all",
            permission: "1",
          }),
        }),
        fetch("https://talent.example.invalid/api/get_headhunters.php", {
          method: "POST",
          body: new URLSearchParams({
            headhunters: "clientAdmin",
            permission: "1",
          }),
        }),
        fetch("https://talent.example.invalid/api/get_headhunters.php", {
          method: "POST",
          body: new URLSearchParams({
            headhunters: "clients",
            permission: "1",
          }),
        }),
      ]);

      for (const response of headhuntersResponses) {
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
      }

      const [allHeadhuntersData, clientAdminHeadhuntersData, clientsHeadhuntersData] = await Promise.all(
        headhuntersResponses.map((res) => res.json())
      );

      const combinedHeadhuntersData = [
        ...allHeadhuntersData.results,
        ...clientAdminHeadhuntersData.results,
        ...clientsHeadhuntersData.results,
      ];

      // 存储猎头数据到IndexedDB
      const db = await openIndexedDB();
      await storeDataInIndexedDB(db, "headhunters", combinedHeadhuntersData);
      console.log("存储猎头数据到IndexedDB");

      // 填充猎头下拉框
      populateHeadhuntersDropdown(combinedHeadhuntersData);
      console.log("填充猎头下拉框");

      // 恢复上次选择的猎头
      const savedHeadhunterId = localStorage.getItem("selectedHeadhunter");
      if (savedHeadhunterId) {
        const headhunter = combinedHeadhuntersData.find(hh => hh.user_id === parseInt(savedHeadhunterId, 10));
        if (headhunter) {
          headhuntersDropdown.value = headhunter.user_id;
          await loadPositionsForHeadhunter(headhunter.user_id);
        }
      }

      console.log("猎头信息更新完成");

    } catch (error) {
      console.error("更新猎头信息失败:", error);
      alert("更新猎头信息失败: " + error.message);
    } finally {
      // 恢复按钮状态
      refreshHeadhunterButton.disabled = false;
      refreshHeadhunterButton.textContent = "更新猎头信息";
    }
  }

