  // 可搜索下拉框功能
  function initializeSearchableDropdown() {
    console.log("初始化可搜索下拉框...");

    // 存储原始选项数据
    let originalOptions = [];
    let filteredOptions = [];

    // 点击下拉框时切换到搜索模式
    headhuntersDropdown.addEventListener("click", function (e) {
      if (!searchableContainer.classList.contains("search-mode-headhunters")) {
        console.log("切换到猎头搜索模式");
        searchableContainer.classList.add("search-mode-headhunters");
        headhuntersSearch.focus();

        // 保存当前选择的值
        const currentValue = headhuntersDropdown.value;

        // 保存原始选项
        originalOptions = Array.from(headhuntersDropdown.options).map(option => ({
          value: option.value,
          text: option.textContent,
          element: option.cloneNode(true)
        }));

        // 初始化搜索框
        headhuntersSearch.value = "";
        filteredOptions = [...originalOptions];
        updateDropdownOptions(filteredOptions);

        // 恢复当前选择
        if (currentValue) {
          headhuntersSearch.value = originalOptions.find(opt => opt.value === currentValue)?.text || "";
          headhuntersDropdown.value = currentValue;
          console.log("恢复猎头搜索框值:", headhuntersSearch.value);
        }
      }
    });

    // 搜索框输入事件
    headhuntersSearch.addEventListener("input", function (e) {
      const searchTerm = e.target.value.toLowerCase();
      console.log("搜索关键词:", searchTerm);

      if (searchTerm === "") {
        filteredOptions = [...originalOptions];
      } else {
        filteredOptions = originalOptions.filter(option =>
          option.text.toLowerCase().includes(searchTerm)
        );
      }

      updateDropdownOptions(filteredOptions);
    });

    // 搜索框失去焦点时切换回下拉模式
    headhuntersSearch.addEventListener("blur", function (e) {
      setTimeout(() => {
        if (!searchableContainer.contains(document.activeElement)) {
          console.log("切换回猎头下拉模式");
          searchableContainer.classList.remove("search-mode-headhunters");

          // 如果有搜索结果，选择第一个匹配项
          if (filteredOptions.length > 0) {
            const selectedOption = filteredOptions[0];
            headhuntersDropdown.value = selectedOption.value;
            headhuntersDropdown.dispatchEvent(new Event("change"));
          }
        }
      }, 200);
    });

    // 搜索框键盘事件
    headhuntersSearch.addEventListener("keydown", function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        if (filteredOptions.length > 0) {
          const selectedOption = filteredOptions[0];
          headhuntersDropdown.value = selectedOption.value;
          headhuntersDropdown.dispatchEvent(new Event("change"));
          searchableContainer.classList.remove("search-mode-headhunters");
        }
      } else if (e.key === "Escape") {
        e.preventDefault();
        searchableContainer.classList.remove("search-mode-headhunters");
        headhuntersSearch.value = "";
      }
    });

    // 更新下拉框选项
    function updateDropdownOptions(options) {
      headhuntersDropdown.innerHTML = "";

      if (options.length === 0) {
        const option = document.createElement("option");
        option.value = "";
        option.textContent = "没有找到匹配的猎头";
        headhuntersDropdown.appendChild(option);
      } else {
        options.forEach(opt => {
          const option = document.createElement("option");
          option.value = opt.value;
          option.textContent = opt.text;
          // 保留原始选项的dataset.data，这对后续功能很重要
          if (opt.element && opt.element.dataset.data) {
            option.dataset.data = opt.element.dataset.data;
          }
          headhuntersDropdown.appendChild(option);
        });
      }
    }
  }

  // 岗位搜索功能
  if (positionsSearch && positionsDropdown) {
    let positionsOriginalOptions = [];
    let positionsFilteredOptions = [];

    // 点击岗位下拉框时切换到搜索模式
    positionsDropdown.addEventListener("click", function (e) {
      if (!searchableContainer.classList.contains("search-mode-positions")) {
        console.log("切换到岗位搜索模式");
        searchableContainer.classList.add("search-mode-positions");
        positionsSearch.focus();

        // 保存当前选择的值
        const currentValue = positionsDropdown.value;

        // 保存原始选项
        positionsOriginalOptions = Array.from(positionsDropdown.options).map(option => ({
          value: option.value,
          text: option.textContent,
          element: option.cloneNode(true)
        }));

        // 初始化搜索框
        positionsSearch.value = "";
        positionsFilteredOptions = [...positionsOriginalOptions];
        updatePositionsDropdownOptions(positionsFilteredOptions);

        // 恢复当前选择
        if (currentValue) {
          positionsSearch.value = positionsOriginalOptions.find(opt => opt.value === currentValue)?.text || "";
          positionsDropdown.value = currentValue;
          console.log("恢复岗位搜索框值:", positionsSearch.value);
        }
      }
    });

    // 岗位搜索框输入事件
    positionsSearch.addEventListener("input", function (e) {
      const searchTerm = e.target.value.toLowerCase();
      console.log("岗位搜索关键词:", searchTerm);

      if (searchTerm === "") {
        positionsFilteredOptions = [...positionsOriginalOptions];
      } else {
        positionsFilteredOptions = positionsOriginalOptions.filter(option =>
          option.text.toLowerCase().includes(searchTerm)
        );
      }

      updatePositionsDropdownOptions(positionsFilteredOptions);
    });

    // 岗位搜索框失去焦点时切换回下拉模式
    positionsSearch.addEventListener("blur", function (e) {
      setTimeout(() => {
        if (!searchableContainer.contains(document.activeElement)) {
          console.log("切换回岗位下拉模式");
          searchableContainer.classList.remove("search-mode-positions");

          // 如果有搜索结果，选择第一个匹配项
          if (positionsFilteredOptions.length > 0) {
            const selectedOption = positionsFilteredOptions[0];
            positionsDropdown.value = selectedOption.value;
            positionsDropdown.dispatchEvent(new Event("change"));
          }
        }
      }, 200);
    });

    // 岗位搜索框键盘事件
    positionsSearch.addEventListener("keydown", function (e) {
      if (e.key === "Enter") {
        e.preventDefault();
        if (positionsFilteredOptions.length > 0) {
          const selectedOption = positionsFilteredOptions[0];
          positionsDropdown.value = selectedOption.value;
          positionsDropdown.dispatchEvent(new Event("change"));
          searchableContainer.classList.remove("search-mode-positions");
        }
      } else if (e.key === "Escape") {
        e.preventDefault();
        searchableContainer.classList.remove("search-mode-positions");
        positionsSearch.value = "";
      }
    });

    // 更新岗位下拉框选项
    function updatePositionsDropdownOptions(options) {
      positionsDropdown.innerHTML = "";

      if (options.length === 0) {
        const option = document.createElement("option");
        option.value = "";
        option.textContent = "没有找到匹配的岗位";
        positionsDropdown.appendChild(option);
      } else {
        options.forEach(opt => {
          const option = document.createElement("option");
          option.value = opt.value;
          option.textContent = opt.text;
          // 保留原始选项的dataset.data，这对策略加载很重要
          if (opt.element && opt.element.dataset.data) {
            option.dataset.data = opt.element.dataset.data;
          }
          positionsDropdown.appendChild(option);
        });
      }
    }
  }

  // 自动初始化函数
  async function autoInitialize() {
    try {
      console.log("开始自动初始化...");

      // 初始化可搜索下拉框
      initializeSearchableDropdown();

      // 每次打开扩展时都调用API获取最新数据
      console.log("调用API获取最新猎头数据");
      await loadInitialData();

    } catch (error) {
      console.error("自动初始化失败:", error);
      // 如果API调用失败，尝试使用缓存数据
      try {
        console.log("API调用失败，尝试使用缓存数据...");
        const db = await openIndexedDB();
        const headhunters = await getDataFromIndexedDB(db, "headhunters");

        if (headhunters && headhunters.length > 0) {
          console.log("使用缓存数据初始化");
          populateHeadhuntersDropdown(headhunters);

          // 恢复上次选择的猎头
          const savedHeadhunterId = localStorage.getItem("selectedHeadhunter");
          if (savedHeadhunterId) {
            const headhunter = headhunters.find(hh => hh.user_id === parseInt(savedHeadhunterId, 10));
            if (headhunter) {
              headhuntersDropdown.value = headhunter.user_id;
              await loadPositionsForHeadhunter(headhunter.user_id);
            }
          }
        } else {
          console.log("缓存数据也为空，显示错误信息");
          headhuntersDropdown.innerHTML = "<option>加载失败，请重试</option>";
        }
      } catch (cacheError) {
        console.error("缓存数据加载也失败:", cacheError);
        headhuntersDropdown.innerHTML = "<option>加载失败，请重试</option>";
      }
    }
  }

  // 级联选择函数：根据猎头ID加载岗位
  async function loadPositionsForHeadhunter(headhunterId) {
    try {
      console.log(`加载猎头 ${headhunterId} 的岗位信息...`);
      positionsDropdown.innerHTML = "<option>加载中...</option>";

      // 调用API获取该猎头的岗位信息
      const formData = new FormData();
      formData.append("headhunter_id", headhunterId);
      formData.append("permission", "1");

      const response = await fetch(
        "https://talent.example.invalid/api/get_jds.php",
        {
          method: "POST",
          body: formData,
        }
      );

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const responseData = await response.text();
      if (responseData.trim() === "") {
        throw new Error("API returned an empty response");
      }

      const jdsData = JSON.parse(responseData);
      const headhunterPositions = Array.isArray(jdsData.results) ? jdsData.results : [];

      // 更新IndexedDB中的岗位数据
      const db = await openIndexedDB();
      await storeDataInIndexedDB(db, "jds", headhunterPositions);

      // 按 position_id 倒序排序
      headhunterPositions.sort((a, b) => b.position_id - a.position_id);

      console.log("排序后的岗位列表是：", headhunterPositions)

      // 填充岗位下拉框
      positionsDropdown.innerHTML = "";
      headhunterPositions.forEach((position) => {
        const option = document.createElement("option");
        option.value = position.position_id;
        option.textContent = `${position.company_name} - ${position.position_name}`;
        option.dataset.data = JSON.stringify(position);
        positionsDropdown.appendChild(option);
      });

      console.log(`成功加载 ${headhunterPositions.length} 个岗位`);

      // 恢复上次选择的岗位（只有在当前猎头下才恢复）
      const savedPosition = localStorage.getItem("selectedPosition");
      const currentHeadhunterId = localStorage.getItem("selectedHeadhunter");

      if (savedPosition && currentHeadhunterId == headhunterId && headhunterPositions.find(p => p.position_id == savedPosition)) {
        positionsDropdown.value = savedPosition;
        // 恢复岗位信息到localStorage（如果不存在）
        const savedPositionData = headhunterPositions.find(p => p.position_id == savedPosition);
        if (savedPositionData) {
          if (!localStorage.getItem("selectedPositionName")) {
            localStorage.setItem("selectedPositionName", savedPositionData.position_name);
          }
          if (!localStorage.getItem("selectedPositionKeywords")) {
            localStorage.setItem("selectedPositionKeywords", savedPositionData.keywords_zh || "");
          }
          if (!localStorage.getItem("selectedCompany")) {
            localStorage.setItem("selectedCompany", savedPositionData.company_name || "");
          }
        }
        console.log("恢复选择的岗位:", savedPosition);
        positionsDropdown.dispatchEvent(new Event("change"));
      } else {
        // 如果岗位不属于当前猎头，清除岗位相关的localStorage
        if (currentHeadhunterId != headhunterId) {
          localStorage.removeItem("selectedPosition");
          localStorage.removeItem("selectedPositionName");
          localStorage.removeItem("selectedPositionKeywords");
          localStorage.removeItem("selectedCompany");
          localStorage.removeItem("selectedStrategy");
        }
      }

    } catch (error) {
      console.error("加载岗位信息失败:", error);
      positionsDropdown.innerHTML = "<option>加载失败</option>";
    }
  }

  // 级联选择函数：根据岗位ID加载策略
  async function loadStrategiesForPosition(positionId) {
    try {
      console.log(`加载岗位 ${positionId} 的策略信息...`);
      const strategyDropdown = document.getElementById("strategyDropdown");
      strategyDropdown.innerHTML = "<option>加载中...</option>";

      // 调用API获取该岗位的策略信息
      const response = await fetch('https://talent.example.invalid/api/get_search_strategy.php', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
          position_id: positionId,
          id: '',
        }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }

      const data = await response.json();
      const strategies = data.results || [];

      // 更新IndexedDB中的策略数据
      const db = await openTalentDB();
      const dataToStore = {
        jds_id: positionId,
        strategies: strategies
      };
      await storeDataInIndexedDB(db, "jds_Strategy", [dataToStore]);

      // 填充策略下拉框
      strategyDropdown.innerHTML = "";

      // 添加默认的"请选择策略"选项
      const defaultOption = document.createElement("option");
      defaultOption.value = "";
      defaultOption.textContent = "请选择策略";
      strategyDropdown.appendChild(defaultOption);

      // 初始化filteredStrategies变量
      let filteredStrategies = [];

      if (strategies && strategies.length > 0) {
        // 按创建时间排序，新的在前
        strategies.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));

        // 根据当前URL过滤策略
        const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
        const currentUrl = tab.url;
        console.log("当前浏览的页面 URL:", currentUrl);

        if (currentUrl.includes("liepin")) {
          filteredStrategies = strategies.filter(item => item.strategy.trim().startsWith("{"));
        } else if (currentUrl.includes("linkedin")) {
          filteredStrategies = strategies.filter(item => item.strategy.trim().startsWith("h"));
        } else if (currentUrl.includes("maimai")) {
          filteredStrategies = strategies.filter(item => item.strategy.trim().startsWith("{"));
        } else {
          console.warn("当前页面不属于 liepin 或 linkedin，未筛选策略");
          filteredStrategies = strategies; // 如果不匹配任何网站，显示所有策略
        }

        if (filteredStrategies.length > 0) {
          filteredStrategies.forEach((strategy, index) => {
            const option = document.createElement("option");
            const prefix = strategy.top_ranked === 1 ? '⭐ ' : '';
            option.value = strategy.strategy;
            option.textContent = prefix + (strategy.name || `策略 ${index + 1}`);
            option.highlighted = strategy.top_ranked;
            strategyDropdown.appendChild(option);
          });
        } else {
          const option = document.createElement("option");
          option.textContent = "暂无符合条件的策略";
          option.value = "";
          strategyDropdown.appendChild(option);
        }
      } else {
        const option = document.createElement("option");
        option.textContent = "暂无策略";
        option.value = "";
        strategyDropdown.appendChild(option);
      }

      console.log(`成功加载 ${strategies ? strategies.length : 0} 个策略`);

      // 恢复上次选择的策略
      const savedStrategy = localStorage.getItem("selectedStrategy");
      if (savedStrategy && filteredStrategies && filteredStrategies.length > 0) {
        // 检查保存的策略是否在当前过滤后的策略列表中
        const strategyExists = filteredStrategies.some(strategy => strategy.strategy === savedStrategy);
        if (strategyExists) {
          strategyDropdown.value = savedStrategy;
          console.log("恢复上次选择的策略:", savedStrategy);
        } else {
          console.log("保存的策略不在当前策略列表中，清除localStorage");
          localStorage.removeItem("selectedStrategy");
          // 确保选择默认选项
          strategyDropdown.value = "";
        }
      } else {
        // 如果没有保存的策略，确保选择默认选项
        strategyDropdown.value = "";
      }

    } catch (error) {
      console.error("加载策略信息失败:", error);
      const strategyDropdown = document.getElementById("strategyDropdown");
      strategyDropdown.innerHTML = "<option>加载失败</option>";
    }
  }

