  async function upload_strategy() {
    const getActiveTabUrl = () => {
      return new Promise((resolve, reject) => {
        chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
          if (tabs && tabs.length) {
            resolve(tabs[0].url);
          } else {
            reject("No active tab found.");
          }
        });
      });
    };

    let linkedInUrl;
    try {
      linkedInUrl = await getActiveTabUrl();
      console.log("当前页面网址:", linkedInUrl);
    } catch (error) {
      console.error(error);
      alert(error)
      return;
    }

    const formData = new FormData();
    formData.append("chatbotID", "__TALENTMATCH_MODEL_01__");
    formData.append("userID", "__TALENTMATCH_USER_01__");
    formData.append("prompt", linkedInUrl);
    formData.append("permission", "1");
    await tryDulpicate()
    async function tryDulpicate() {
      try {
        const response = await fetch('https://model.example.invalid/api/completions/quora.php', {
          method: 'POST',
          body: formData,
        });
        const data = await response.json();
        const content = data.choices[0]?.message?.content;
        console.log("API response content:", content);

        if (!content) {
          throw new Error("Empty strategy content received from Quora API");
        }

        const positionID = localStorage.getItem("selectedPosition");
        if (!positionID) {
          throw new Error("Missing position ID in localStorage");
        }

        const params = new URLSearchParams({
          position_id: positionID,
          strategy: linkedInUrl
        });

        let isDuplicate = false;
        try {
          const dupResponse = await fetch('https://talent.example.invalid/api/duplicate_search_strategy.php', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/x-www-form-urlencoded'
            },
            body: params.toString()
          });
          const dupData = await dupResponse.json();

          if (dupData.duplicate === "yes") {
            isDuplicate = true;
            console.log('Duplicate found, exiting early:', dupData);
          } else if (dupData.success) {
            console.log('Duplicate check passed:', dupData);
          } else {
            console.error('Duplicate check failed:', dupData.message);
          }
        } catch (dupError) {
          console.error('Error during duplicate check:', dupError);
        }

        if (isDuplicate) {
          saveButton.textContent = "重复策略";
          saveButton.style.background = "orange";
        } else {
          const strategyFormData = new FormData();
          strategyFormData.append("position_id", positionID);
          strategyFormData.append("name", content);
          strategyFormData.append("strategy", linkedInUrl);
          strategyFormData.append("source", "linkedin");

          await fetch('https://talent.example.invalid/api/add_search_strategy.php', {
            method: 'POST',
            body: strategyFormData,
          });

          saveButton.textContent = "保存成功";
          saveButton.style.background = "green";
        }
      } catch (error) {
        console.error("Error saving session:", error);
        //alert(error)
      } finally {
        saveButton.disabled = false;
      }
    }
  }

