          // 提取每个公司信息并发送API请求
          async function extractCompanyDetailsAndSendPrompt() {
            const companyDetails = [];

            // 查找所有符合class="artdeco-list__item pl3 pv3"的元素
            const companyItems = document.querySelectorAll('.artdeco-list__item.pl3.pv3');

            // 获得id = global-typeahead-search-input的input里面填入的值，如果没有则为空字符串""
            const searchInputElement = document.getElementById('global-typeahead-search-input');
            const searchQuery = searchInputElement ? searchInputElement.value.trim() : "";

            companyItems.forEach(item => {
              const company = {};

              // 通过搜索词指定文件名
              company.searchQuery = searchQuery

              // 提取公司名
              const companyNameElement = item.querySelector('.artdeco-entity-lockup__title');
              if (companyNameElement) {
                company.name = companyNameElement.textContent.trim();
              }

              // 提取行业
              const industryElement = item.querySelector('[data-anonymize="industry"]');
              if (industryElement) {
                company.industry = industryElement.textContent.trim();
              }

              // 提取职工人数
              const employeeCountElement = item.querySelector('.li-i18n-linkto._link_1derdc._view-all-employees_1derdc');
              if (employeeCountElement) {
                company.employeeCount = employeeCountElement.textContent.trim();
              }

              // 提取详细信息
              const detailsElement = item.querySelector('.t-12.t-black--light.mb3');
              if (detailsElement) {
                company.details = detailsElement.textContent.trim();
              }

              // 提取招聘状态
              const recruitmentStatusElement = item.querySelector('.nowrap-ellipsis.text-align-left');
              if (recruitmentStatusElement) {
                company.recruitmentStatus = recruitmentStatusElement.textContent.trim();
              }

              // 提取公司 URL
              const companyLinkElement = item.querySelector('a');
              if (companyLinkElement) {
                company.url = companyLinkElement.href;
              }

              // 如果该公司信息存在，添加到公司详情数组中
              if (Object.keys(company).length > 0) {
                companyDetails.push(company);
              }
            });


            // 处理提取的公司信息，发送到API
            async function processCompanyDetails(companyDetails) {
              // 使用 map 创建一个包含所有异步操作的数组
              const promises = companyDetails.map(async (company, i) => {
                const prompt = `
                  公司名称：${company.name}
                  行业：${company.industry}
                  简介：${company.details}
                `;

                try {
                  // 第一次调用 sendPromptToAPI 函数，获取第一个 botResponse
                  const botResponse = await sendPromptToAPI(prompt, "__TALENTMATCH_MODEL_02__");

                  // 第二次调用 sendPromptToAPI，传递公司对象的 JSON 字符串
                  const promptAll = `要求：${searchQuery} 公司信息：${JSON.stringify(company)}`  // 使用 JSON.stringify 来转换公司对象
                  const ifWeNeedResponse = await sendPromptToAPI(promptAll, "__TALENTMATCH_MODEL_03__");

                  // 将返回的结果分别存入 company 对象中
                  company.botResponse = botResponse;  // 第一个 botResponse
                  company.ifWeNeed = ifWeNeedResponse;  // 第二个 botResponse

                  // 打印包含 botResponse 和 ifWeNeed 的公司信息到控制台
                  console.log("Updated Company Details with Bot Response: ", company);

                  // 向 localhost:8000/LinkedInDetail 发送 POST 请求
                  await sendToLocalServer(company, i, companyDetails.length);
                } catch (error) {
                  console.error("Error sending prompt to API:", error);
                }
              });

              // 使用 Promise.all 并发执行所有请求
              await Promise.all(promises);
            }


            // 发送请求到API
            async function sendPromptToAPI(prompt, botID) {
              const formData = new FormData();
              const apiURL = "https://model.example.invalid/api/completions/quora.php";
              formData.append("chatbotID", botID);
              formData.append("userID", "__TALENTMATCH_USER_01__");
              formData.append("prompt", prompt);
              formData.append("permission", "1");

              try {
                const response = await fetch(apiURL, { method: "POST", body: formData });
                if (!response.ok) {
                  throw new Error(`HTTP error! status: ${response.status}`);
                }
                const result = await response.json();
                return result.choices[0].message.content;
              } catch (error) {
                console.error("Error sending prompt to API:", error);
              }
            }

            // 发送数据到 localhost 服务器
            async function sendToLocalServer(company, i, totalCompanies) {
              const url = 'http://localhost:8000/LinkedInDetail';
              try {
                const response = await fetch(url, {
                  method: 'POST',
                  headers: { 'Content-Type': 'application/json' },
                  body: JSON.stringify(company),
                });

                if (!response.ok) {
                  throw new Error(`HTTP error! status: ${response.status}`);
                }

                // 判断是否是最后一项，如果是，弹出 alert
                if (i === totalCompanies - 1) {
                  console.log('Data successfully sent to localhost server.');
                }
              } catch (error) {
                console.error('Error sending data to localhost server:', error);
              }
            }

            // 等待所有操作完成后再返回
            await processCompanyDetails(companyDetails);
            return companyDetails;
          }

