  async function pullSession(executeType = "") {
    // 从 localStorage 获取 selectedPosition
    const selectedPosition = localStorage.getItem('selectedPosition');

    if (!selectedPosition) {
      console.error('No selected position found in localStorage.');
      return null;  // 返回 null 如果没有找到 selectedPosition
    }

    try {
      // 发送 POST 请求到 https://talent.example.invalid/api/get_search_strategy.php
      const response = await fetch('https://talent.example.invalid/api/get_search_strategy.php', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
          position_id: selectedPosition, // 通过 localStorage 获取的 selectedPosition
          id: '', // 空的 ID
        }),
      });

      // 检查请求是否成功
      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }

      // 获取返回的 JSON 数据
      const data = await response.json();

      // 假设返回数据包含 results 字段，打印结果
      if (data.results) {
        console.log('Results:', data.results);

        // 如果 executeType 是 "liepin"
        if (executeType === "liepin") {
          // 如果 results 数组是空数组，直接返回 null
          if (data.results.length === 0) {
            return null;
          }

          // 从数组尾部开始寻找第一个 name 以 "全部词" 开头的对象
          for (let i = data.results.length - 1; i >= 0; i--) {
            if (data.results[i].name && data.results[i].strategy.startsWith("{")) {
              console.log('Found item for liepin:', data.results[i]);
              return data.results[i];  // 返回找到的对象
            }
          }
        }

        // 如果 executeType 是 "linkedIn"
        else if (executeType === "linkedIn") {
          // 如果 results 数组是空数组，直接返回 null
          if (data.results.length === 0) {
            return null;
          }

          // 从数组尾部开始寻找第一个 name 以 "岗位" 开头的对象
          for (let i = data.results.length - 1; i >= 0; i--) {
            if (data.results[i].name && data.results[i].strategy.startsWith("h")) {
              console.log('Found item for linkedIn:', data.results[i]);
              return data.results[i];  // 返回找到的对象
            }
          }
        }

        // 如果没有找到符合条件的对象，返回 null
        console.log('No matching item found.');
        return null;

      } else {
        console.log('No results found in the response.');
        return null;
      }

    } catch (error) {
      console.error('Error pulling session:', error);
      return null;  // 出现错误时返回 null
    }
  }

