      async function scrollPageDown() {
        const scrollableDiv = document.querySelector(
          "div.overflow-x-hidden.overflow-y-auto.p4"
        );
        let scrollAttempts = 0;
        const scrollStep = 100; // 每次滚动的距离
        const maxAttempts = 64; // 向下滚动的总次数 (8秒 = 32次 * 250毫秒)

        function scroll() {
          scrollableDiv.scrollBy(0, scrollStep);
          scrollAttempts++;
          if (scrollAttempts < maxAttempts) {
            setTimeout(scroll, 250);
          }
        }
        scroll();
        await new Promise((resolve) => setTimeout(resolve, 16000));
      }

