          const spans = element.querySelectorAll("span");

          // 检查是否存在任意一个 <span> 的内容是 "Viewed"
          const hasViewed = Array.from(spans).some(
            (span) => span.textContent.trim() === "Viewed"
          );

          // 检查是否包含 "View profile"
          const hasViewProfile = Array.from(spans).some(
            (span) => span.textContent.trim() === "View profile"
          );

          // 如果不包含 "Viewed" 和 "View profile"，保留该元素
          return !hasViewed && !hasViewProfile;
