        // 将该函数放到你的脚本中并调用 goNextOrFinish()
        async function goNextOrFinish() {
          // 简单的等待函数
          const wait = ms => new Promise(res => setTimeout(res, ms));

          // 判定元素是否“可点击”的实用函数
          function isClickable(el) {
            if (!el) return false;
            // disabled 属性 / aria-disabled
            if (el.disabled) return false;
            if (el.getAttribute && el.getAttribute('aria-disabled') === 'true') return false;

            // 样式相关（display/visibility/pointer-events）
            const style = window.getComputedStyle(el);
            if (style.display === 'none' || style.visibility === 'hidden' || style.pointerEvents === 'none') return false;

            // 在文档流外（例如 display:block 但 position absolute 且在不可见区域也算不可点击）
            const rect = el.getBoundingClientRect();
            if (rect.width === 0 || rect.height === 0) return false;

            // offsetParent 为 null 通常表示元素不可见（除了 fixed 元素）
            if (el.offsetParent === null && style.position !== 'fixed') return false;

            return true;
          }

          // 尝试按优先级找到“下一页”按钮（覆盖常见情况和你给出的样例）
          function findNextButton() {
            // 1. 精确类名（样例中常见）
            const a = document.querySelector('.artdeco-pagination__button--next');
            if (a) return a;

            // 2. 通过 aria-label（英文/中文/部分场景）
            const b = document.querySelector('button[aria-label*="Next"], button[aria-label*="下一页"], button[aria-label*="Next page"], button[aria-label*="下一"]');
            if (b) return b;

            // 3. id（如果你保留 ember ID）
            const c = document.querySelector('#ember4511');
            if (c) return c;

            // 4. 最后按文本内容查找（更宽松）
            const btns = Array.from(document.querySelectorAll('button'));
            const found = btns.find(btn => {
              const txt = (btn.textContent || '').trim();
              // 包含“Next”或“下一页”或常见分页箭头符号
              return /(^Next$)|(^下一页$)|\bNext\b|\b下一页\b|›|»|下一/.test(txt);
            });
            if (found) return found;

            return null;
          }

          try {
            const btn = findNextButton();

            if (!btn) {
              console.log('Next 按钮未找到 — 结束任务');
              document.title = '已完成';
              return;
            }

            if (!isClickable(btn)) {
              console.log('Next 按钮存在但不可点击（可能是最后一页或被禁用） — 结束任务');
              document.title = '已完成';
              return;
            }

            // 点击并等待页面响应（根据页面不同，时间可调整）
            console.log('点击 Next 按钮：', btn);
            btn.click();

            // 等待短暂时间给页面加载/DOM 更新（可按需调整）
            await wait(7000);

            // 如果 processCurrentPage 可用则调用它
            if (typeof processCurrentPage === 'function') {
              console.log('调用 processCurrentPage() 处理新页面');
              return processCurrentPage();
            } else {
              console.warn('processCurrentPage 未定义 — 只完成翻页操作');
              return;
            }
          } catch (err) {
            console.error('翻页时发生异常：', err);
            // 出错时也设置已完成以避免无限重试
            document.title = '已完成';
          }
        }


