      // 定义 sendPromptToAPI 函数，使其在脚本中可用
      async function sendPromptToAPI(prompt) {
        const formData = new FormData();
        let apiURL = "https://model.example.invalid/api/completions/quora.php";
        formData.append("chatbotID", "__TALENTMATCH_MODEL_05__");
        formData.append("userID", "__TALENTMATCH_USER_01__");

        const deepMatchRegex = /深匹([\s\S]*?)(?=个人信息)/;
        const personalInfoRegex = /个人信息([\s\S]*)/;
        const deepMatch = prompt.match(deepMatchRegex);
        const personalInfoMatch = prompt.match(personalInfoRegex);
        if (deepMatch && personalInfoMatch) {
          prompt = `${deepMatch[0]} \n ${personalInfoMatch[0]}`;
        } else if (deepMatch) {
          prompt = deepMatch[0];
        }
        formData.append("prompt", prompt);
        formData.append("permission", "1");

        try {
          const response = await fetch(apiURL, {
            method: "POST",
            body: formData,
          });

          if (!response.ok) {
            throw new Error(`HTTP error! status: ${response.status}`);
          }

          const result = await response.json();
          let content = result.choices[0].message.content;
          console.log("API response:", result);
          console.log("API response String:", content);

          return content;
        } catch (error) {
          console.error("Error sending prompt to API:", error);
        }
      }

      // 页面向下滚动 8 秒
      async function scrollPageDown() {
        const scrollableDiv = document.querySelector(
          "div.overflow-x-hidden.overflow-y-auto.p4"
        );
        let scrollAttempts = 0;
        const scrollStep = 100; // 每次滚动的距离
        const maxAttempts = 64; // 向下滚动的总次数 (8秒 = 32次 * 250毫秒)

        function scroll() {
          scrollableDiv.scrollBy(0, scrollStep);
          scrollAttempts++;
          if (scrollAttempts < maxAttempts) {
            setTimeout(scroll, 250);
          }
        }
        scroll();
        await new Promise((resolve) => setTimeout(resolve, 16000));
      }

      async function scrollPageDownShort() {
        const scrollableDiv = document.querySelector(
          "div.overflow-x-hidden.overflow-y-auto.p4"
        );

        let scrollAttempts = 0;
        const scrollStep = 100;       // Distance scrolled per step
        const delay = 100;            // Delay between each scroll in ms
        const maxAttempts = 10;       // Total attempts: 20 * 100ms = 2000ms (2 seconds)

        function scroll() {
          scrollableDiv.scrollBy(0, scrollStep); // Scroll downward
          scrollAttempts++;
          if (scrollAttempts < maxAttempts) {
            setTimeout(scroll, delay);
          }
        }

        scroll();
        await new Promise((resolve) => setTimeout(resolve, delay * maxAttempts));
      }

      async function scrollPageUp() {
        const scrollableDiv = document.querySelector(
          "div.overflow-x-hidden.overflow-y-auto.p4"
        );

        let scrollAttempts = 0;
        const scrollStep = 100;       // Distance scrolled per step
        const delay = 100;            // Delay between each scroll in ms
        const maxAttempts = 10;       // Total attempts: 20 * 100ms = 2000ms (2 seconds)

        function scroll() {
          scrollableDiv.scrollBy(0, -scrollStep); // Scroll upward
          scrollAttempts++;
          if (scrollAttempts < maxAttempts) {
            setTimeout(scroll, delay);
          }
        }

        scroll();
        await new Promise((resolve) => setTimeout(resolve, delay * maxAttempts));
      }

