        const scrollStep = 100;       // Distance scrolled per step
        const delay = 100;            // Delay between each scroll in ms
        const maxAttempts = 10;       // Total attempts: 20 * 100ms = 2000ms (2 seconds)

        function scroll() {
          scrollableDiv.scrollBy(0, scrollStep); // Scroll downward
          scrollAttempts++;
          if (scrollAttempts < maxAttempts) {
            setTimeout(scroll, delay);
          }
        }

        scroll();
        await new Promise((resolve) => setTimeout(resolve, delay * maxAttempts));
