        function getLiepinKeywords(iframeDocument) {
          let result = {};

          const workInfoItems = iframeDocument.querySelector('.rd-work-info-head');
          const workJobTitle = iframeDocument.querySelector(`.job-name`);

          if (workInfoItems) {
            result.workInfoContent = workInfoItems.textContent.trim().replace(/（.*$/, '').trim();
          }

          if (workInfoItems) {
            result.workInfoContent = workInfoItems.textContent
              .trim()
              .replace(/（.*$/, "")
              .trim();
          } else {
          }

          if (workJobTitle) {
            result.workInfoContent += ` ${workJobTitle.textContent.trim()}`;
          }

          const eduInfo = iframeDocument.querySelector(".resume-detail-edu-info");
          if (eduInfo) {
            const schoolName = eduInfo.querySelector(".school-name");
            const schoolSpecial = eduInfo.querySelector(".school-special");

            result.eduInfoContent = {
              schoolName: schoolName ? schoolName.textContent.trim() : "",
              schoolSpecial: schoolSpecial ? schoolSpecial.textContent.trim() : "",
            };
          }

          const lastLoginSpan = Array.from(
            iframeDocument.querySelectorAll('div.BTVlw span')
          ).find(el => el.textContent.includes('最后一次登录时间'));

          if (lastLoginSpan) {
            // 原始文本例如："最后一次登录时间：2024/12/28"
            const text = lastLoginSpan.textContent.trim();
            // 用正则提取日期部分
            const match = text.match(/(\d{4}\/\d{2}\/\d{2})/);
            result.lastLoginDate = match ? match[1] : '';
          } else {
            result.lastLoginDate = '';
          }

          return result;
        }

        let firstRun = true;  // 增加一个标志，用于判断是否是第一次运行

