  // 自定义岗位信息部分======================================================================================================================
  const customDropdown = document.getElementById("customDropdown"); // 获取自定义Dropdown
  const customFormContainer = document.getElementById("customFormContainer"); // 用于显示表单的div
  localStorage.removeItem("CustomJobRequirement");

  // 从 IndexedDB 获取之前保存的岗位并填充到 Dropdown
  async function populateCustomDropdown() {
    const db = await openIndexedDB();
    const customJobs = await getDataFromIndexedDB(db, "CustomJob");

    // 从 localStorage 中获取上次选中的值
    const lastSelectedValue =
      localStorage.getItem("LastSelectedCustomJob") || "none";

    // 清除当前的选项，重新填充
    customDropdown.innerHTML = `
    <option value="none" ${lastSelectedValue === "none" ? "selected" : ""
      }>不使用自定义岗位信息</option>
    <option value="add" ${lastSelectedValue === "add" ? "selected" : ""
      }>增加一个自定义岗位</option>
    <option value="edit" ${lastSelectedValue === "edit" ? "selected" : ""
      }>修改岗位要求</option>
  `;

    // 从 CustomJob 表中获取岗位并填充
    customJobs.forEach((job) => {
      const option = document.createElement("option");
      option.value = job.id;
      option.textContent = job.name; // 显示岗位名称

      // 如果是上次保存的选中项，设置为选中状态
      if (job.id == lastSelectedValue) {
        option.selected = true;
      }

      customDropdown.appendChild(option);
    });

    // 如果上次选择的是一个已保存的自定义岗位，自动加载其需求
    if (
      lastSelectedValue &&
      lastSelectedValue !== "none" &&
      lastSelectedValue !== "add" &&
      lastSelectedValue !== "edit"
    ) {
      const selectedJob = customJobs.find((job) => job.id == lastSelectedValue);
      console.log(`自定义岗位信息：${JSON.stringify(selectedJob)}`)
      if (selectedJob) {
        localStorage.setItem("CustomJobRequirement", selectedJob.requirement);
        localStorage.setItem("selectedPositionName", selectedJob.name);
        // 清理系统岗位ID，标记使用自定义岗位
        localStorage.removeItem("selectedPosition");
        localStorage.setItem("usingCustomJob", "true");
        // 动态更新当前岗位显示
        updatePositionText(selectedJob.name);
      }
    }
  }

  function getFormattedDate() {
    const today = new Date();
    const month = String(today.getMonth() + 1).padStart(2, "0"); // 月份从0开始，需要加1，并保证是两位数
    const day = String(today.getDate()).padStart(2, "0"); // 获取日期并确保两位数
    return `暂存职位 ${month}-${day}`;
  }

  // 当 Dropdown 变化时的监听器
  customDropdown.addEventListener("change", async (event) => {
    const selectedValue = event.target.value;

    // 将最后选择的值存入 localStorage
    localStorage.setItem("LastSelectedCustomJob", selectedValue);

    // 只有当选择的是实际岗位（不是add、edit、none）时才更新selectedPositionName
    if (selectedValue !== "add" && selectedValue !== "edit" && selectedValue !== "none") {
      const selectedOption = event.target.options[event.target.selectedIndex];
      const customJobName = selectedOption ? selectedOption.textContent.trim() : '';
      console.log(customJobName);

      localStorage.setItem("selectedPositionName", customJobName);
      // 清理系统岗位ID，标记使用自定义岗位
      localStorage.removeItem("selectedPosition");
      localStorage.setItem("usingCustomJob", "true");
      // 动态更新当前岗位显示
      updatePositionText(customJobName);
    }

    // 判断是否选择了 "增加一个自定义岗位"
    if (selectedValue === "add") {
      // 清理系统岗位ID，标记使用自定义岗位
      localStorage.removeItem("selectedPosition");
      localStorage.setItem("usingCustomJob", "true");
      // 弹出一个表单，允许用户输入岗位名称和岗位需求
      const timestamp = new Date().getTime(); // 获取当前时间戳
      customFormContainer.innerHTML = `
      <div>
      <br>
        <label>岗位名称: <input id="jobName" type="text" value="${getFormattedDate()}"></label>
         <br>
        <label>岗位需求: <textarea id="jobRequirement"></textarea></label>
         <br>
        <button id="saveCustomJob">保存</button>
      </div>
    `;

      // 监听保存按钮点击事件
      document
        .getElementById("saveCustomJob")
        .addEventListener("click", async () => {
          const cleanString = str => str.replace(/\s+/g, '');
          const jobName = document.getElementById("jobName").value;
          const jobRequirement =
            document.getElementById("jobRequirement").value;

          // 保存到 IndexedDB
          const db = await openIndexedDB();
          const transaction = db.transaction(["CustomJob"], "readwrite");
          const store = transaction.objectStore("CustomJob");
          store.put({
            id: cleanString(jobName),
            name: jobName,
            requirement: jobRequirement,
          });

          await transaction.complete;
          await populateCustomDropdown(); // 更新下拉框
          customFormContainer.innerHTML = ""; // 清空表单
        });
    } else if (selectedValue === "edit") {
      // 清理系统岗位ID，标记使用自定义岗位
      localStorage.removeItem("selectedPosition");
      localStorage.setItem("usingCustomJob", "true");
      // 弹出一个表单，允许用户输入岗位名称和岗位需求
      const timestamp = new Date().getTime();
      customFormContainer.innerHTML = `
      <div>
      <br>
        <label>岗位名称: <input id="jobName" type="text" value="${localStorage.getItem("selectedPositionName")}"></label>
         <br>
        <label>岗位需求: <textarea id="jobRequirement">${localStorage.getItem("CustomJobRequirement")}</textarea></label>
         <br>
        <button id="editCustomJob">保存</button>
      </div>
    `;

      // 监听保存按钮点击事件
      document
        .getElementById("editCustomJob")
        .addEventListener("click", async () => {
          const cleanString = str => str.replace(/\s+/g, '');
          if (cleanString(document.getElementById("jobName").value) !== cleanString(localStorage.getItem("selectedPositionName"))) {
            alert("岗位名称不存在")
            return;
          }
          const jobName = document.getElementById("jobName").value;
          const jobRequirement = document.getElementById("jobRequirement").value;

          // 保存到 IndexedDB
          const db = await openIndexedDB();
          const transaction = db.transaction(["CustomJob"], "readwrite");
          const store = transaction.objectStore("CustomJob");
          store.delete(jobName);
          // store.delete(localStorage.getItem("CustomJobRequirement"));
          store.put({
            id: cleanString(jobName),
            name: jobName,
            requirement: jobRequirement,
          });

          await transaction.complete;
          await populateCustomDropdown();
          customFormContainer.innerHTML = "";
        });
    } else if (selectedValue !== "none") {
      // 获取已保存的自定义岗位信息
      const db = await openIndexedDB();
      const customJobs = await getDataFromIndexedDB(db, "CustomJob");
      const selectedJob = customJobs.find((job) => job.id == selectedValue);

      if (selectedJob) {
        // 将岗位需求保存到 localStorage
        console.log("尝试保存自定义职位到localstorage");
        localStorage.setItem("CustomJobRequirement", selectedJob.requirement);
      }

      // 清空表单容器
      customFormContainer.innerHTML = "";
    } else {
      // 如果选择了 "不使用自定义岗位信息"，清除 localStorage 中的保存
      localStorage.removeItem("CustomJobRequirement");
      customFormContainer.innerHTML = "";
    }
  });

