  document.getElementById("save-filter-session-LinkedIn").addEventListener("click", async () => {
    const saveButton = document.getElementById("save-filter-session-LinkedIn");
    saveButton.disabled = true;
    saveButton.style.background = "grey";
    saveButton.textContent = "处理中...";


    const getActiveTabUrl = () => {
      return new Promise((resolve, reject) => {
        chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
          if (tabs && tabs.length) {
            resolve(tabs[0].url);
          } else {
            reject("No active tab found.");
          }
        });
      });
    };

    function getNumCountFromLinkedIn() {
      return new Promise((resolve, reject) => {
        chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
          chrome.tabs.sendMessage(
            tabs[0].id,
            { action: "getNumCount" },
            (response) => {
              if (chrome.runtime.lastError) {
                reject(chrome.runtime.lastError);
              } else if (response && response.numCount) {
                resolve(response.numCount);
              } else {
                reject("numCount not found");
              }
            }
          );
        });
      });
    }

    const numCount = await getNumCountFromLinkedIn();
    console.log("numCount:", numCount);

    const numberCount = numCount.replace(/\s*results?$/i, '').trim();
    console.log("onlyNumber:", numberCount);

    let linkedInUrl;
    try {
      linkedInUrl = await getActiveTabUrl();
      console.log("当前页面网址:", linkedInUrl);
    } catch (error) {
      console.error(error);
      alert(error)
      return;
    }

    const formData = new FormData();
    formData.append("chatbotID", "__TALENTMATCH_MODEL_01__");
    formData.append("userID", "__TALENTMATCH_USER_01__");
    formData.append("prompt", linkedInUrl);
    formData.append("permission", "1");
    await tryDulpicate()
    async function tryDulpicate() {
      try {
        const response = await fetch('https://model.example.invalid/api/completions/quora.php', {
          method: 'POST',
          body: formData,
        });
        const data = await response.json();
        const content = data.choices[0]?.message?.content;
        console.log("API response content:", content);

        if (!content) {
          throw new Error("Empty strategy content received from Quora API");
        }

        const positionID = localStorage.getItem("selectedPosition");
        if (!positionID) {
          throw new Error("Missing position ID in localStorage");
        }

        const params = new URLSearchParams({
          position_id: positionID,
          strategy: linkedInUrl
        });

        let isDuplicate = false;
        try {
          const dupResponse = await fetch('https://talent.example.invalid/api/duplicate_search_strategy.php', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/x-www-form-urlencoded'
            },
            body: params.toString()
          });
          const dupData = await dupResponse.json();

          if (dupData.duplicate === "yes") {
            isDuplicate = true;
            console.log('Duplicate found, exiting early:', dupData);
          } else if (dupData.success) {
            console.log('Duplicate check passed:', dupData);
          } else {
            console.error('Duplicate check failed:', dupData.message);
          }
        } catch (dupError) {
          console.error('Error during duplicate check:', dupError);
        }


        if (isDuplicate) {
          saveButton.textContent = "重复策略";
          saveButton.style.background = "orange";
        } else {
          const strategyFormData = new FormData();
          strategyFormData.append("position_id", positionID);
          strategyFormData.append("name", `${numberCount} ` + content);
          strategyFormData.append("strategy", linkedInUrl);
          strategyFormData.append("source", "linkedin");

          await fetch('https://talent.example.invalid/api/add_search_strategy.php', {
            method: 'POST',
            body: strategyFormData,
          });

          saveButton.textContent = "保存成功";
          saveButton.style.background = "green";
        }
      } catch (error) {
        console.error("Error saving session:", error);
        saveButton.textContent = "保存失败";
        saveButton.style.background = "red";
      } finally {
        saveButton.disabled = false;
      }
    }
  });





  document.getElementById("uploadBtnLinkedIn").addEventListener("click", () => {
    // 触发文件选择
    const fileInput = document.getElementById("jsonFileLinkedIn");
    fileInput.click();

    // 当用户选择文件时触发的事件
    fileInput.addEventListener("change", () => {
      const file = fileInput.files[0];

      if (file) {
        const reader = new FileReader();

        // 文件读取成功后的回调
        reader.onload = function (event) {
          try {
            // 解析 JSON 文件内容
            const jsonContent = JSON.parse(event.target.result);

            // 获取 url 属性
            const url = jsonContent.url;

            // 检查 url 是否存在
            if (url) {
              // 打开该 URL (新标签页)
              window.open(url, "_blank");
            } else {
              alert("JSON 文件中没有找到 'url' 属性");
            }
          } catch (error) {
            alert("无法解析 JSON 文件");
          }
        };

        // 读取文件内容
        reader.readAsText(file);
      } else {
        alert("请选择一个 JSON 文件");
      }
    });
  });

  // 该函数将在页面上下文中执行
  function getPageDescribe() {
    const elements = [
      ...document.querySelectorAll(
        ".pv3._container_bguac2._container-divider_bguac2._column_c69tab"
      ),
      ...document.querySelectorAll(".pt2.ph4.flex.flex-wrap.list-style-none"),
    ];
    let describeContent = "";

    elements.forEach((element, index) => {
      describeContent += element.innerText || element.textContent;
      if (index < elements.length - 1) {
        describeContent += "\n\n"; // 在每个元素之间添加两个空行
      }
    });

    return describeContent;
  }

  // 折叠按钮部分
  if (toggleButton) {
    toggleButton.addEventListener("click", () => {
      console.log("折叠/展开更多功能");
      // 切换内容的展开/折叠状态
      if (collapsibleContent.classList.contains("open")) {
        // 当前是展开状态，执行折叠
        collapsibleContent.classList.remove("open");
        toggleButton.textContent = "展开更多功能";
      } else {
        // 当前是折叠状态，执行展开
        collapsibleContent.classList.add("open");
        toggleButton.textContent = "折叠更多功能";
      }
    });
  }

  //猎聘导入公司功能
  if (1) {
    document.getElementById("LiepinBatchCompanyFiltering").addEventListener("click", async () => {
      const button = document.getElementById("LiepinBatchCompanyFiltering");
      button.disabled = true;
      button.textContent = "处理中...";
      button.style.background = "grey";

      try {
        // 从 localStorage 获取 positionId
        const positionId = localStorage.getItem("selectedPosition");
        const selectedPositionKeywords = localStorage.getItem("selectedPositionKeywords");
        const customJobRequirement = localStorage.getItem("CustomJobRequirement");
        const positionName = localStorage.getItem("selectedPositionName");
        const inchargeID = localStorage.getItem("selectedHeadhunter");
        const company_name = localStorage.getItem("selectedCompany");

        console.log(
          "从 localStorage 中获取的数据:",
          selectedPositionKeywords,
          customJobRequirement,
          positionName,
          inchargeID,
          positionId,
          company_name
        );
        if (!positionId) {
          throw new Error("未在 localStorage 中找到选中的职位");
        }

        // 构建 API 请求数据
        const formData = new FormData();
        formData.append("position_id", positionId);

        // 调用 API 获取对标公司列表
        const response = await fetch("https://talent.example.invalid/api/get_ai_jd.php", {
          method: "POST",
          body: formData,
        });

        if (!response.ok) {
          throw new Error(`API 请求失败: ${response.status}`);
        }

        const result = await response.json();
        console.log("API 返回结果:", result);

        // 解析对标公司列表
        const similarCompanyList = result.results[0]?.similar_company_list;
        if (!similarCompanyList) {
          throw new Error("API 返回结果中未找到对标公司列表");
        }

        const companies = similarCompanyList
          .split("\n")
          .map((company) => company.trim())
          .filter((company) => company && !company.includes(" "));

        if (companies.length === 0) {
          throw new Error("对标公司列表中未找到有效公司");
        }

        console.log("解析后的公司列表:", companies);

        // 将公司分批处理，每批最多 8 个公司，总共最多 10 批
        const batchSize = 8;
        const maxBatches = 10;
        const batches = [];
        for (let i = 0; i < companies.length; i += batchSize) {
          batches.push(companies.slice(i, i + batchSize));
          if (batches.length >= maxBatches) break;
        }
        console.log("公司批次:", batches);

        // 获取职位参数，准备发送给background.js
        const params = {
          selectedPositionName: localStorage.getItem("selectedPositionName"),
          selectedPositionKeywords: localStorage.getItem("selectedPositionKeywords"),
          customJobRequirement: localStorage.getItem("CustomJobRequirement"),
          positionName: localStorage.getItem("selectedPositionName"),
          inchargeID: localStorage.getItem("selectedHeadhunter"),
          positionID: localStorage.getItem("selectedPosition"),
          company_name: localStorage.getItem("selectedCompany")
        };

        console.log("传递的参数:", params);

        // 发送消息给background.js，保存参数并开始监听
        chrome.runtime.sendMessage({
          action: "startBatchInjection",
          params: params
        });

        // 获取当前活动标签页并注入脚本
        await new Promise((resolve, reject) => {
          chrome.tabs.query({ active: true, currentWindow: true }, function (tabs) {
            const activeTab = tabs[0];
            if (activeTab && activeTab.id) {
              chrome.scripting.executeScript({
                target: { tabId: activeTab.id },
                func: injectedScript,
                args: [batches], // 将所有批次一次性传递
              }, (results) => {
                if (chrome.runtime.lastError) {
                  reject(new Error(chrome.runtime.lastError.message));
                } else {
                  resolve(results);
                }
              });
            } else {
              reject(new Error("未找到当前活动的标签页"));
            }
          });
        });

        // 注入脚本完成后显示提示
        alert("AI 处理已完成");

      } catch (error) {
        console.error("处理对标公司时出错:", error);
        alert(`发生错误: ${error.message}`);
      } finally {
        button.disabled = false;
        button.textContent = "对标公司打开";
        button.style.background = "";
      }
    });

    // 注入到页面中的脚本，包含所有逻辑
    async function injectedScript(batches) {
      // 辅助函数：设置公司搜索
      function setCompanySearch(companyNames) {
        const searchInput = document.querySelector("#rc_select_4");
        if (searchInput) {
          searchInput.focus();
          searchInput.value = companyNames;
          searchInput.dispatchEvent(new Event("input", { bubbles: true }));
          const enterKeyEvent = new KeyboardEvent("keydown", {
            key: "Enter",
            bubbles: true,
            cancelable: true,
            keyCode: 13,
            which: 13
          });
          searchInput.dispatchEvent(enterKeyEvent);
          console.log("已设置公司搜索为:", companyNames);
        } else {
          console.error("未找到公司搜索输入框");
          throw new Error("未找到公司搜索输入框");
        }
      }

      // 辅助函数：将筛选下拉框切换为“目前”
      function setDropdownToCurrent() {
        const allDropdowns = Array.from(document.querySelectorAll('.ant-select-selection-item'))
          .filter(el => el.textContent.trim() === '全部');
        if (allDropdowns.length >= 2) {
          const secondDropdown = allDropdowns[1];
          const selector = secondDropdown.closest('.ant-select-selector');

          if (selector) {
            // Full click simulation
            const mouseDown = new MouseEvent('mousedown', {
              bubbles: true,
              cancelable: true,
              view: window
            });

            selector.dispatchEvent(mouseDown);
            selector.dispatchEvent(new MouseEvent('mouseup', { bubbles: true }));
            selector.dispatchEvent(new MouseEvent('click', { bubbles: true }));

            console.log('Successfully clicked the SECOND "全部" dropdown!');

            const interval = setInterval(() => {
              const dropdownOptions = document.querySelectorAll(".ant-select-item-option-content");
              const target = Array.from(dropdownOptions).find(el => el.textContent.includes("目前"));
              if (target) {
                target.click();
                console.log("已将筛选条件设置为：目前");
                clearInterval(interval);
              }
            }, 200);
            setTimeout(() => clearInterval(interval), 3000); // 超时保护
          } else {
            console.log('Could not find parent selector for the second dropdown');
          }
        } else {
          console.log(`Found only ${allDropdowns.length} dropdown(s) with "全部" text (need at least 2)`);
        }
      }

      // 辅助函数：点击全选复选框
      function clickAllCheck() {
        const allCheck = document.querySelector('input[name="allCheck"]');
        if (allCheck) {
          allCheck.click();
          console.log("已点击全选复选框");
        } else {
          console.warn("未找到全选复选框");
        }
      }

      // 辅助函数：点击批量打开按钮
      function clickBatchOpen() {
        const batchButton = document.querySelector('[data-tlg-elem-id="h_pc_search_batch_view_res_btn"]');
        if (batchButton) {
          batchButton.click();
          console.log("已点击批量打开按钮");
        } else {
          console.warn("未找到批量打开按钮");
        }
      }

      // 辅助函数：获取当前活动页码
      function getCurrentActivePage() {
        const activePageElement = document.querySelector("li.ant-pagination-item-active");
        return activePageElement ? parseInt(activePageElement.innerText) : 1;
      }

      // 辅助函数：检查是否有下一页
      function checkHasNextPage() {
        const currentPage = getCurrentActivePage();
        const nextPageElement = document.querySelector(`li.ant-pagination-item[title="${currentPage + 1}"]`);
        return !!nextPageElement;
      }

      // 辅助函数：翻到下一页
      function goToNextPage(nextPageNumber) {
        const nextPageElement = document.querySelector(`li.ant-pagination-item[title="${nextPageNumber}"]`);
        if (nextPageElement) {
          nextPageElement.click();
          console.log(`已翻到第 ${nextPageNumber} 页`);
        } else {
          console.log("没有更多页面可翻");
        }
      }

      // 辅助函数：检查是否有简历
      async function hasResumes() {
        const emptyElement = document.querySelector(".ant-empty");
        const resumeCards = document.querySelectorAll(".detail-resume-card-wrap");
        if (emptyElement) {
          console.log("检测到无简历提示");
          return false;
        }
        if (resumeCards.length > 0) {
          console.log(`检测到 ${resumeCards.length} 份简历`);
          return true;
        }
        return false; // 默认无简历
      }

      // 辅助函数：等待
      function wait(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
      }

      // 主逻辑：按顺序处理所有批次
      try {
        const maxPages = 5;

        for (let batchIndex = 0; batchIndex < batches.length; batchIndex++) {
          const batch = batches[batchIndex];
          const companyNames = batch.join(" "); // 确保公司名称以空格分隔
          console.log(`正在处理批次 ${batchIndex + 1}/${batches.length}: ${companyNames}`);

          setDropdownToCurrent(); // 新增：设置筛选为“目前”
          await wait(4000); // 等待下拉框和页面结果更新

          // 设置公司搜索并等待结果加载
          setCompanySearch(companyNames);
          await wait(5000); // 等待搜索结果加载

          // 检查是否有简历
          const resumesExist = await hasResumes();
          if (!resumesExist) {
            console.log(`批次 ${companyNames} 无简历可打开，跳到下一个批次`);
            await wait(2000); // 短暂延迟后处理下一个批次
            continue; // 跳到下一个批次
          }

          // 处理每页，最多 5 页
          for (let page = 1; page <= maxPages; page++) {
            console.log(`开始处理第${page}页`)
            clickAllCheck();
            await wait(1000); // 等待全选操作完成
            clickBatchOpen();
            await wait(5000); // 等待批量打开完成

            // 批量打开简历后，通知background.js开始批量注入
            console.log("批量打开完成，通知background.js开始批量注入");

            // 等待一段时间，确保简历标签页已经打开
            await wait(3000);

            if (!checkHasNextPage()) {
              console.log(`批次 ${companyNames} 已无更多页面`);
              break;
            }

            goToNextPage(getCurrentActivePage() + 1);
            await wait(5000); // 等待翻页完成
          }

          // 每个批次之间添加额外延迟，确保页面稳定
          await wait(2000);
        }

        console.log("所有批次处理完成");
        alert("AI 处理已完成"); // 在页面上下文中显示提示

      } catch (error) {
        console.error("注入脚本执行出错:", error);
        alert(`注入脚本出错: ${error.message}`);
      }
    }
  }

