  // 导入cookies并重定向到根域名
  document.getElementById("importCookies").addEventListener("click", () => {
    document.getElementById("fileInput").click();
  });

  document.getElementById("fileInput").addEventListener("change", (event) => {
    const file = event.target.files[0];
    if (!file) return;
    const reader = new FileReader();

    reader.onload = async (e) => {
      try {
        const cookies = JSON.parse(e.target.result);
        const tabs = await new Promise((resolve) => chrome.tabs.query({ active: true, currentWindow: true }, resolve));
        const activeTab = tabs[0];
        const currentUrl = new URL(activeTab.url);
        const rootDomain = `${currentUrl.protocol}//${currentUrl.hostname}`;
        const targetDomain = currentUrl.hostname.replace(/^www\./, "");

        function cookieUrl(cookie, fallbackProtocol = currentUrl.protocol) {
          const domain = (cookie.domain || targetDomain).replace(/^\./, "");
          const path = cookie.path || "/";
          const protocol = cookie.secure ? "https:" : fallbackProtocol;
          return `${protocol}//${domain}${path}`;
        }

        function normalizeSameSite(sameSite) {
          if (!sameSite) return undefined;
          const sameSiteMap = {
            none: "no_restriction",
            no_restriction: "no_restriction",
            lax: "lax",
            strict: "strict",
            unspecified: "unspecified",
          };
          return sameSiteMap[String(sameSite).toLowerCase()];
        }

        function dedupeCookies(items) {
          const map = new Map();
          items.forEach((cookie) => {
            const key = [
              cookie.domain || targetDomain,
              cookie.path || "/",
              cookie.name
            ].join("|");
            map.set(key, cookie);
          });
          return Array.from(map.values());
        }

        async function removeCookie(cookie) {
          await new Promise((resolve) => {
            chrome.cookies.remove({ url: cookieUrl(cookie), name: cookie.name }, resolve);
          });
        }

        async function setCookie(cookie) {
          const details = {
            url: cookieUrl(cookie, "https:"),
            name: cookie.name,
            value: cookie.value,
            path: cookie.path || "/",
            secure: Boolean(cookie.secure),
            httpOnly: Boolean(cookie.httpOnly),
          };

          if (cookie.domain && !cookie.hostOnly) details.domain = cookie.domain;
          if (cookie.expirationDate) details.expirationDate = cookie.expirationDate;
          const sameSite = normalizeSameSite(cookie.sameSite);
          if (sameSite) details.sameSite = sameSite;

          await new Promise((resolve) => {
            chrome.cookies.set(details, () => {
              if (chrome.runtime.lastError) {
                console.error(`设置 Cookie 失败: ${cookie.name}`, chrome.runtime.lastError.message);
              }
              resolve();
            });
          });
        }

        const existingCookies = await new Promise((resolve) => {
          chrome.cookies.getAll({ domain: targetDomain }, resolve);
        });
        const incomingCookies = dedupeCookies(cookies);
        const incomingNames = new Set(incomingCookies.map((cookie) => cookie.name));
        const cookiesToRemove = existingCookies.filter((cookie) => {
          const domain = cookie.domain.replace(/^\./, "");
          return domain === targetDomain || domain.endsWith(`.${targetDomain}`) || incomingNames.has(cookie.name);
        });

        await Promise.all(cookiesToRemove.map(removeCookie));
        for (const cookie of incomingCookies) {
          await setCookie(cookie);
        }

        chrome.tabs.update(activeTab.id, { url: rootDomain });
      } catch (error) {
        console.error("导入 Cookies 失败:", error);
        alert(`导入 Cookies 失败: ${error.message}`);
      } finally {
        event.target.value = "";
      }
    };

    reader.readAsText(file);
  });



