  document.getElementById("jsonFile").addEventListener("change", function () {
    const fileInput = document.getElementById("jsonFile");
    const file = fileInput.files[0];

    if (file) {
      const reader = new FileReader();

      // 文件读取成功后执行
      reader.onload = function (e) {
        const fileContent = e.target.result;

        // 向当前页面发送消息
        chrome.tabs.query(
          { active: true, currentWindow: true },
          function (tabs) {
            chrome.tabs.sendMessage(tabs[0].id, { jsonContent: fileContent });
          }
        );
      };

      reader.readAsText(file); // 开始读取文件内容
    } else {
      alert("Please select a JSON file");
    }
  });


  function sendTabMessageWithContentScriptRetry(tabId, message, callback) {
    const send = (isRetry) => {
      chrome.tabs.sendMessage(tabId, message, (response) => {
        const errorMessage = chrome.runtime.lastError?.message || "";
        if (!errorMessage) {
          callback(null, response);
          return;
        }

        const receiverMissing =
          /Could not establish connection|Receiving end does not exist/i.test(
            errorMessage
          );
        if (isRetry || !receiverMissing) {
          callback(new Error(errorMessage));
          return;
        }

        console.warn(
          "[Popup] Content script 未连接，尝试重新注入后重试:",
          message.action
        );
        chrome.scripting.executeScript(
          {
            target: { tabId },
            files: [
              "src/core/quoraApiGuard.js",
              "src/core/content.js",
              "assets/libs/xlsx.mini.min.js",
            ],
          },
          () => {
            const injectionError = chrome.runtime.lastError?.message || "";
            if (injectionError) {
              callback(new Error(injectionError));
              return;
            }
            send(true);
          }
        );
      });
    };

    send(false);
  }

  saveSessionButton.addEventListener("click", async () => {
    console.log("点击了保存上传session")
    // ---------- UI 工具 ----------
    function setButtonStatus(text, bgColor, disabled = true) {
      saveSessionButton.textContent = text;
      saveSessionButton.style.background = bgColor;
      saveSessionButton.disabled = disabled;
    }

    // ---------- 数据工具 ----------
    function sortKeysDeep(value) {
      if (Array.isArray(value)) {
        return value.map(sortKeysDeep);
      }
      if (value && typeof value === 'object') {
        return Object.keys(value)
          .sort()
          .reduce((acc, key) => {
            acc[key] = sortKeysDeep(value[key]);
            return acc;
          }, {});
      }
      return value;
    }

    function hasMeaningfulValue(value) {
      if (value === null || value === undefined) return false;
      if (typeof value === 'string') return value.trim() !== '';
      if (typeof value === 'number' || typeof value === 'boolean') return true;
      if (Array.isArray(value)) return value.length > 0 && value.some(hasMeaningfulValue);
      if (typeof value === 'object') {
        const keys = Object.keys(value);
        return keys.length > 0 && Object.values(value).some(hasMeaningfulValue);
      }
      return false;
    }

    function normalizeStrategy(sessionText) {
      if (typeof sessionText !== 'string') return null;

      const trimmed = sessionText.trim();
      if (!trimmed || trimmed === 'null' || trimmed === 'undefined') return null;

      try {
        const parsed = JSON.parse(trimmed);

        if (!hasMeaningfulValue(parsed)) {
          return null;
        }

        return JSON.stringify(sortKeysDeep(parsed));
      } catch (e) {
        // 不是 JSON 字符串时，退化为普通文本判断
        return trimmed ? trimmed : null;
      }
    }

    function buildSessionCandidates(response) {
      const rawCandidates = [
        {
          key: 'search_resume_session',
          raw: response.sessionData
        }
      ];

      // 先过滤空 session
      const nonEmptyCandidates = rawCandidates
        .map(item => {
          const normalized = normalizeStrategy(item.raw);
          return {
            ...item,
            normalized
          };
        })
        .filter(item => !!item.normalized);

      // 再做本地去重（同样内容只保留一份，优先保留先出现的）
      const uniqueMap = new Map();
      for (const item of nonEmptyCandidates) {
        if (!uniqueMap.has(item.normalized)) {
          uniqueMap.set(item.normalized, item);
        }
      }

      return Array.from(uniqueMap.values());
    }

    // ---------- 接口工具 ----------
    async function checkDuplicate(positionId, strategy) {
      const params = new URLSearchParams({
        position_id: positionId,
        strategy
      });

      try {
        const response = await fetch('https://talent.example.invalid/api/duplicate_search_strategy.php', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded'
          },
          body: params.toString()
        });

        const data = await response.json();

        if (data.duplicate === "yes") {
          return true;
        }

        if (!data.success) {
          console.warn('Duplicate search failed:', data.message);
        }

        return false;
      } catch (error) {
        console.error('Error during duplicate search:', error);
        // 查重异常时，不强行判重，交给后续上传决定
        return false;
      }
    }

    async function getStrategySummary(session) {
      const formData = new FormData();
      formData.append("chatbotID", "__TALENTMATCH_MODEL_14__");
      formData.append("userID", "__TALENTMATCH_USER_01__");
      formData.append("prompt", session);
      formData.append("permission", "1");

      const response = await fetch('https://model.example.invalid/api/completions/quora.php', {
        method: 'POST',
        body: formData,
      });

      const data = await response.json();
      return data.choices[0]?.message?.content || '';
    }

    async function uploadStrategy({
      positionID,
      session,
      apiSourceParam,
      scrapeData
    }) {
      const content = await getStrategySummary(session);
      if (!content) {
        throw new Error('没有拿到策略总结内容');
      }

      const strategyFormData = new FormData();
      strategyFormData.append("position_id", positionID);
      strategyFormData.append(
        "name",
        `${scrapeData.headhunterName || ''} ${scrapeData.numberCount || ''}${content}`
      );
      strategyFormData.append("strategy", session);

      if (apiSourceParam) {
        strategyFormData.append("source", apiSourceParam);
      }

      const response = await fetch('https://talent.example.invalid/api/add_search_strategy.php', {
        method: 'POST',
        body: strategyFormData,
      });

      return response;
    }

    // ---------- 开始处理 ----------
    setButtonStatus("处理中...", "grey", true);
    console.log("开始处理")

    chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
      if (tabs.length === 0) {
        console.error("No active tab found.");
        setButtonStatus("失败", "red", false);
        return;
      }

      const currentUrl = tabs[0].url;
      let actionName = "";
      let apiSourceParam = "";

      if (currentUrl.includes("liepin.com")) {
        actionName = "getSessionDataAndRemark";
        apiSourceParam = "liepin";
      } else if (currentUrl.includes("maimai.cn")) {
        actionName = "getSessionDataAndRemarkMaiMai";
        apiSourceParam = "maimai";
      } else if (currentUrl.includes("zhaopin.com")) {
        actionName = "getSessionDataAndRemarkZhaopin";
        apiSourceParam = "zhilian";
      } else if (currentUrl.includes("linkedin.com")) {
        actionName = "getSessionDataAndRemarkLinkedIn";
        apiSourceParam = "linkedin";
      } else {
        alert("当前页面不支持保存策略");
        setButtonStatus("不支持的页面", "red", false);
        return;
      }

      console.log(`当前来源: ${apiSourceParam}, 发送指令: ${actionName}`);

      sendTabMessageWithContentScriptRetry(
        tabs[0].id,
        { action: actionName },
        async (messageError, response) => {
          if (messageError) {
            console.error("Error: ", messageError.message);
            setButtonStatus("失败", "red", false);
            return;
          }

          if (!response) {
            console.log("未能提取到 Session 数据");
            setButtonStatus("失败", "red", false);
            return;
          }

          try {
            const scrapeData = response;
            const positionID = localStorage.getItem("selectedPosition");

            if (!positionID) {
              console.error("Missing required parameter: position_id");
              setButtonStatus("缺少岗位ID", "red", false);
              return;
            }

            const candidates = buildSessionCandidates(response);

            if (!candidates.length) {
              console.warn('search_resume_session 为空，跳过上传');
              setButtonStatus("Session为空", "grey", false);
              return;
            }

            console.log("非空且本地去重后的 candidates:", candidates);

            // 2. 服务端查重
            const uploadableCandidates = [];
            const duplicateCandidates = [];

            for (const candidate of candidates) {
              const isDuplicate = await checkDuplicate(positionID, candidate.normalized);
              if (isDuplicate) {
                duplicateCandidates.push(candidate);
              } else {
                uploadableCandidates.push(candidate);
              }
            }

            console.log("可上传 candidates:", uploadableCandidates);
            console.log("重复 candidates:", duplicateCandidates);

            if (!uploadableCandidates.length) {
              setButtonStatus("Session重复", "grey", false);
              return;
            }

            // 3. 上传所有“不重复”的候选
            let successCount = 0;
            let failCount = 0;

            for (const candidate of uploadableCandidates) {
              try {
                await uploadStrategy({
                  positionID,
                  session: candidate.normalized,
                  apiSourceParam,
                  scrapeData
                });

                successCount++;
                console.log('策略上传成功');
              } catch (error) {
                failCount++;
                console.error('策略上传失败:', error);
              }
            }

            // 4. 更新 UI
            if (successCount > 0 && failCount === 0) {
              setButtonStatus(`保存成功(${successCount})`, "green", false);
            } else if (successCount > 0 && failCount > 0) {
              setButtonStatus(`部分成功(${successCount}/${uploadableCandidates.length})`, "orange", false);
            } else {
              setButtonStatus("保存失败", "red", false);
            }
          } catch (error) {
            console.error('请求失败:', error);
            setButtonStatus("保存失败", "red", false);
          }
        }
      );
    });
  });
  // 保存Session部分的功能.
