              ws["C1"] = { v: "Current Position" };
              ws["D1"] = { v: "Link" };
              ws["E1"] = { v: "Salary" };
              ws["F1"] = { v: "Resume" };
              ws["G1"] = { v: "Raw Resume" };
              ws["H1"] = { v: "Recent Active" };
              ws["I1"] = { v: "Raw Comment" };
              ws["J1"] = { v: "Comment" };
              ws["K1"] = { v: "Liepin Key Words" };
              ws["L1"] = { v: "Gold Collar" };
              ws["M1"] = { v: "是否重复" }; // Duplicate Status
              ws["N1"] = { v: "上传情况" }; // Upload Status

              for (let i = 0; i < collectedData.length; i++) {
                let row = i + 2;
                let item = collectedData[i];
                ws["A" + row] = { v: item.Name || '' };
                ws["B" + row] = { v: item.Company || '' };
                ws["C" + row] = { v: item.Position || '' };
                ws["D" + row] = { v: item.link || '' };
                ws["E" + row] = { v: item.Salary || '' };
                ws["F" + row] = { v: item.processedResume || '' };
                ws["G" + row] = { v: item.rawResume || '' };
                ws["H" + row] = { v: item.recentActive || '' };
                ws["I" + row] = { v: item.rawComment || '' };
                ws["J" + row] = { v: item.factComment || '' };
                ws["K" + row] = { v: '' };
                ws["L" + row] = { v: '' };
                ws["M" + row] = { v: item.duplicateStatus || '' };
                ws["N" + row] = { v: item.uploadStatus || '' };
              }
              let lastRow = collectedData.length + 1;
              ws["!ref"] = `A1:N${lastRow}`; // Update range to include N column

