        const collectedData = [];

        function overrideFetch() {
          const originalFetch = window.fetch;
          window.fetch = function (...args) {
            const requestUrl = args[0];
            if (typeof requestUrl === "string" && requestUrl.includes("jsononly=1")) {
              return originalFetch(...args).then(async response => {
                const clone = response.clone();
                try {
                  const status = response.status;
                  const text = await clone.text();

                  if (!text || text.trim() === "") {
                    return response;
                  }
                  if (!response.ok) {
                    return response;
                  }

                  const json = JSON.parse(text);
                  if (json?.data?.card?.id && json?.data?.card?.trackable_token) {
                    userId = json.data.card.id;
                    const trackableToken = json.data.card.trackable_token;
                    currentLink = `https://maimai.cn/profile/detail?dstu=${userId}&trackable_token=${trackableToken}`;
                    console.log("Captured MaiMai Link:", currentLink);
                  }
                } catch (e) {
                  console.error("Error parsing response:", e);
                  console.log("Failed response text:", text);
                }
                return response;
              });
            }
            return originalFetch(...args);
          };
        }
        overrideFetch();

        function formatDateFromLastLogin(lastLoginDate) {
          const now = new Date();
          let targetDate;

          if (typeof lastLoginDate === 'string' &&
            /今日活跃|在线|刚刚活跃/.test(lastLoginDate)) {
            targetDate = now;
          }
          else if (typeof lastLoginDate === 'string' &&
            /近一周活跃/.test(lastLoginDate)) {
            targetDate = new Date(now);
            targetDate.setDate(targetDate.getDate() - 7);
          }
          else if (typeof lastLoginDate === 'string' &&
            /近一月活跃/.test(lastLoginDate)) {
            targetDate = new Date(now);
            targetDate.setMonth(targetDate.getMonth() - 1);
          }
          else {
            return '';
          }

          // Format YYYY-MM-DD 00:00:00
          const Y = targetDate.getFullYear();
          const M = String(targetDate.getMonth() + 1).padStart(2, '0');
          const D = String(targetDate.getDate()).padStart(2, '0');
          return `${Y}-${M}-${D} 00:00:00`;
        }

