      // 处理单个批次的公司
      async function processBatch(batchIndex) {
        console.log(`\n===== 开始处理第 ${batchIndex + 1} 批公司 =====`);

        const companies = batches[batchIndex];
        if (!companies || companies.length === 0) {
          console.log(`第 ${batchIndex + 1} 批公司列表为空，跳过`);
          return false;
        }

        console.log(`第 ${batchIndex + 1} 批将处理以下公司: ${companies.join(', ')}`);

        // 首先点击"就职公司"元素（只在第一批时执行）
        if (batchIndex === 0) {
          let clickSuccess = clickCompanyElement();
          if (!clickSuccess) {
            console.log('尝试备用方法...');
            clickSuccess = clickCompanyElementByXPath();
          }

          if (!clickSuccess) {
            console.log('无法点击"就职公司"元素，流程终止');
            return false;
          }

          // 等待0.5秒
          await wait(500);
        } else {
          // 非第一批时，header应该已经在上一批完成后被点击过了
          console.log(`第 ${batchIndex + 1} 批：使用已打开的"就职公司"选择框`);
        }

        // 依次处理每个公司
        for (let i = 0; i < companies.length; i++) {
          const company = companies[i];
          await processCompany(company);

          // 如果不是最后一个公司，等待一下再处理下一个
          if (i < companies.length - 1) {
            await wait(1000);
          }
        }

        console.log(`✅ 第 ${batchIndex + 1} 批公司处理完成！`);
        return true;
      }

      // 主执行函数
      async function executeCompanySearch() {
        console.log('开始执行公司搜索流程...');
        console.log(`共有 ${batches.length} 批公司需要处理`);

        // 处理第一批公司
        const firstBatchSuccess = await processBatch(0);

        if (!firstBatchSuccess) {
          console.log('❌ 第一批公司处理失败，流程终止');
          return;
        }

        // 第一批完成后的占位符 - 在这里可以添加自定义逻辑
        console.log('\n🔄 第一批公司处理完成，准备执行后续逻辑...');


        // 占位符：为后续批次处理预留的逻辑
        await handleBatchCompletion(0, positionKeywords, positionName, incharge_id, position_id, company_name);

        // 如果有多批，继续处理剩余批次
        if (batches.length > 1) {
          console.log(`\n还有 ${batches.length - 1} 批公司待处理...`);

          for (let batchIndex = 1; batchIndex < batches.length; batchIndex++) {
            console.log(`\n⏳ 等待 2 秒后处理下一批...`);
            await wait(2000);

            const batchSuccess = await processBatch(batchIndex);

            if (!batchSuccess) {
              console.log(`❌ 第 ${batchIndex + 1} 批公司处理失败，继续下一批`);
              continue;
            }

            // 每批完成后的占位符逻辑
            await handleBatchCompletion(batchIndex, positionKeywords, positionName, incharge_id, position_id, company_name);
          }
        }

        console.log('\n🎉 所有批次的公司处理完成！');
      }

