      // ── 4) 你的滚动和点击逻辑不变 ──
      async function realScrollForDuration(durationMs = 30000, pxPerFrame = 20) {
        const end = performance.now() + durationMs;
        function step(now) {
          window.scrollBy(0, pxPerFrame);
          if (now < end) requestAnimationFrame(step);
        }
        requestAnimationFrame(step);
      }

      async function clickCardElement(card, idx) {
        const jobLink = card.querySelector("a.job-name");
        if (!jobLink) {
          console.log(`No link in card ${idx + 1}`);
          return;
        }
        jobLink.scrollIntoView({ behavior: "instant", block: "center" });
        jobLink.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
        console.log(`Clicked card ${idx + 1}`);
        // wait for its XHR to fire
        await new Promise(res => setTimeout(res, 1500));
      }

      async function processJobCards() {
        const cards = Array.from(document.querySelectorAll(".job-list-container .card-area"))
          .filter(card =>
            !card.classList.contains("has-flag") &&
            !(card.querySelector(".boss-name")?.textContent.includes("某"))
          );

        if (cards.length >= 2) {
          // 1) click second card first
          await clickCardElement(cards[1], 1);
          // 2) then click first card
          await clickCardElement(cards[0], 0);
          // 3) then click the rest from index 2 onward
          for (let i = 2; i < cards.length; i++) {
            await clickCardElement(cards[i], i);
          }
        } else {
          // fallback: just click in order
          for (let i = 0; i < cards.length; i++) {
            await clickCardElement(cards[i], i);
          }
        }

        console.log("✅ All cards processed");
      }

