      async function clickCardElement(card, idx) {
        const jobLink = card.querySelector("a.job-name");
        if (!jobLink) {
          console.log(`No link in card ${idx + 1}`);
          return;
        }
        jobLink.scrollIntoView({ behavior: "instant", block: "center" });
        jobLink.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
        console.log(`Clicked card ${idx + 1}`);
        await new Promise((res) => setTimeout(res, 1500));
      }

      let totalCount = 0;

      async function processJobCards() {
        const cards = Array.from(document.querySelectorAll(".position-job-container .job-card-box")).filter(
          (card) =>
            !card.classList.contains("has-flag") &&
            !(card.querySelector(".boss-name")?.textContent.includes("某"))
        );

        function shouldSkipBySalary(card) {
          const salaryEl = card.querySelector(".job-salary");
          if (!salaryEl) return false;
          const text = salaryEl.textContent || "";
          return text.includes("天");
        }

        if (cards.length >= 2) {
          const sequence = [1, 0, ...Array.from({ length: cards.length - 2 }, (_, i) => i + 2)];
          for (let seqIdx = 0; seqIdx < sequence.length; seqIdx++) {
            const idx = sequence[seqIdx];
            if (shouldSkipBySalary(cards[idx])) {
              console.log(`↪️ 跳过卡片（页面索引 ${idx}，薪资含“天”，不计入总数）`);
              continue;
            }
            totalCount++;
            console.log(`🕵️ 正在处理第 ${totalCount} 张卡（页面索引：${idx}）`);
            await clickCardElement(cards[idx], idx);
            if (totalCount >= 100) return;
          }
        } else {
          for (let i = 0; i < cards.length; i++) {
            totalCount++;
            console.log(`🕵️ 正在处理第 ${totalCount} 张卡（页面索引：${i}）`);
            if (shouldSkipBySalary(cards[i])) {
              console.log(`↪️ 跳过卡片 ${totalCount} （薪资含“天”）`);
            } else {
              await clickCardElement(cards[i], i);
            }
            if (totalCount >= 100) return;
          }
        }

        console.log("✅ 本页所有卡片处理完毕，共看到 " + totalCount + " 张卡。");
      }

      async function scrapeJobs() {
        while (totalCount < 100) {
          console.log(`🔍 开始滚动（已看到 ${totalCount} 张卡），为本页加载卡片…`);
          await new Promise((resolve) => {
            realScrollForDuration(3000, 20);
            setTimeout(resolve, 3000);
          });

          console.log("🔍 本页滚动结束，开始处理岗位卡片（已看到 " + totalCount + " 张卡）");
          await processJobCards();

          if (totalCount >= 100) break;

          const nextBtn = document.querySelector(".options-pages a[ka='page-next']");
          if (nextBtn && !nextBtn.classList.contains("disabled")) {
            console.log("➡️ 本页处理完毕，点击下一页 →");
            nextBtn.click();
            await new Promise((res) => setTimeout(res, 5000));
          } else {
            console.log("❌ 找不到下一页按钮或已到最后一页，停止全部抓取。");
            break;
          }
        }

        try { chrome.runtime.sendMessage({ action: "releaseBatchUploadLock" }); } catch (e) {} window.__talentMatchBatchRunning = false; try { chrome.runtime.sendMessage({ action: "releaseBatchUploadLock" }); } catch (e) {} window.__talentMatchBatchRunning = false; document.title = "已完成";
        console.log("🎯 总共看到并尝试了 " + totalCount + " 张卡，任务结束。");
      }

