      // ── 1) 定义将在 page context 执行的拦截器 ──
      function pageInterceptor() {
        // fetch 拦截
        const origFetch = window.fetch;
        window.fetch = async function (...args) {
          let url = args[0];
          if (url instanceof Request) url = url.url;
          if (typeof url === "string" && url.includes("detail.json?securityId")) {
            console.log("🛰️ fetch →", url);
            const resp = await origFetch.apply(this, args);
            resp.clone().json()
              .then(json => {
                console.log("📄 detail.json (via fetch):", json);
                window.handleDetailJson && window.handleDetailJson(json.zpData);
              })
              .catch(e => console.error("⚠️ fetch JSON error:", e));
            return resp;
          }
          return origFetch.apply(this, args);
        };

        // XHR 拦截
        const OrigXHR = window.XMLHttpRequest;
        window.XMLHttpRequest = function () {
          const xhr = new OrigXHR();
          let reqUrl = "";
          const oOpen = xhr.open;
          xhr.open = function (m, u, ...r) {
            reqUrl = u;
            return oOpen.call(this, m, u, ...r);
          };
          const oSend = xhr.send;
          xhr.send = function (...s) {
            if (reqUrl.includes("detail.json?securityId")) {
              xhr.addEventListener("readystatechange", () => {
                if (xhr.readyState === 4) {
                  try {
                    const json = JSON.parse(xhr.responseText);
                    console.log("📄 detail.json (via XHR):", json);
                    window.handleDetailJson && window.handleDetailJson(json.zpData);
                  } catch (e) {
                    console.error("⚠️ XHR JSON error", e);
                  }
                }
              });
            }
            return oSend.apply(this, s);
          };
          return xhr;
        };

        console.log("✅ Page network interceptors installed");
      }


