    // 创建输入字段函数
    function createInputField(labelText, name, value, hidden = false) {
      const label = document.createElement("label");
      label.textContent = labelText;
      label.style.display = "block";
      label.style.marginTop = "5px";

      const input = document.createElement("input");
      input.type = "text";
      input.name = name;
      input.value = value;
      input.style.width = "100%";
      input.style.padding = "5px";
      input.style.marginTop = "5px";
      input.style.boxSizing = "border-box";

      const div = document.createElement("div");
      div.appendChild(label);
      div.appendChild(input);

      if (hidden) {
        div.style.display = "none";
      }

      return div;
    }

    // 创建textarea字段函数
    function createTextareaField(labelText, name, value) {
      const label = document.createElement("label");
      label.textContent = labelText;
      label.style.display = "block";
      label.style.marginTop = "5px";

      const textarea = document.createElement("textarea");
      textarea.name = name;
      textarea.value = value;
      textarea.style.width = "100%";
      textarea.style.height = "100px";
      textarea.style.padding = "5px";
      textarea.style.marginTop = "5px";
      textarea.style.boxSizing = "border-box";

      const div = document.createElement("div");
      div.appendChild(label);
      div.appendChild(textarea);

      // 监听 textarea 的变化，仅当 name 为 'comment' 时更新 commentToTrainData
      if (name === "comment") {
        textarea.addEventListener("input", function () {
          commentToTrainData = textarea.value;
          // console.log('commentToTrainData updated:', commentToTrainData);
        });
      }

      return div;
    }

    // 创建select字段函数
    function createSelectField(
      labelText,
      name,
      options,
      selectedValue,
      hidden = false
    ) {
      const label = document.createElement("label");
      label.textContent = labelText;
      label.style.display = "block";
      label.style.marginTop = "5px";

      const select = document.createElement("select");
      select.name = name;
      select.style.width = "100%";
      select.style.padding = "5px";
      select.style.marginTop = "5px";
      select.style.boxSizing = "border-box";

      options.forEach((option) => {
        const opt = document.createElement("option");
        opt.value = option.value;
        opt.textContent = option.text;
        if (String(option.value) === String(selectedValue)) {
          opt.selected = true;
        }
        select.appendChild(opt);
      });

      const div = document.createElement("div");
      div.appendChild(label);
      div.appendChild(select);

      if (hidden) {
        div.style.display = "none";
      }

      return div;
    }

