                        function calculateLength(str) {
                          var length = 0;
                          for (var i = 0; i < str.length; i++) {
                            var char = str.charAt(i);
                            if (char.match(/[\u4e00-\u9fa5]/)) {
                              length += 2;
                            } else {
                              length += 1;
                            }
                          }
                          return length;
                        }

