  refreshCurrentButton.addEventListener("click", async () => {
    refreshCurrentButton.disabled = true;
    refreshCurrentButton.textContent = "刷新中...";
    isRefreshing = true;

    // 获取ID和职位描述
    const savedPosition = localStorage.getItem("selectedPosition");

    // 安全的解码函数
    function decodeUnicode(str) {
      return str.replace(/\\u[\dA-F]{4}/gi, function (match) {
        return String.fromCharCode(parseInt(match.replace(/\\u/g, ""), 16));
      });
    }

    try {
      // 发送请求到API
      const formdata = new FormData();
      formdata.append("permission", "1");
      formdata.append("position_id", savedPosition);

      const myHeaders = new Headers({
        // 如果需要设置任何头部信息，可以在此处添加
      });

      const requestOptions = {
        method: "POST",
        headers: myHeaders,
        body: formdata,
        redirect: "follow",
      };

      const response = await fetch(
        "https://talent.example.invalid/api/get_ai_jd.php",
        requestOptions
      );
      const result = await response.json();

      // 解码返回的数据
      const positionName = decodeUnicode(result.results[0].position_name);
      let summary = decodeUnicode(result.results[0].matching_req || result.results[0].summary);

      console.log("Position Name:", positionName || null);
      console.log("Summary:", summary.replace(/\r\n/g, "\n") || null);

      // 打开IndexedDB
      const db = await openIndexedDB();

      // 获取jds表中的所有条目
      const jdsEntries = await getDataFromIndexedDB(db, "jds", savedPosition);

      // 在数组中找到position_id匹配的条目
      const jdsEntry = jdsEntries.find(
        (entry) => entry.position_id === Number(savedPosition)
      );

      if (jdsEntry) {
        console.log(jdsEntry.company_name);

        // 要插入的文本
        const companyText = "";
        let flag = false;
        // 处理加分项
        const keyword1 = "加分项";
        if (summary.includes(keyword1)) {
          const index = summary.indexOf(keyword1);
          summary = summary.substring(0, index) + companyText + "，" + summary.substring(index);
          flag = true
        }
        // 处理初筛要求：
        if (summary.includes("初筛要求：")) {
          const index = summary.indexOf("初筛要求：") + "初筛要求：".length;
          summary = summary.substring(0, index) + " " + companyText + summary.substring(index);
          flag = true
        }
        // 处理深匹要求：
        if (summary.includes("深匹要求：")) {
          const index = summary.indexOf("深匹要求：") + "深匹要求：".length;
          summary = summary.substring(0, index) + " " + companyText + summary.substring(index);
          flag = true
        }
        // 如果都没有包含，就加到最后
        if (!flag) {
          summary += `，${companyText}`;
        }

        summary = summary.replace(/我们不需要在.*?的人/g, '');
        summary += `，${companyText}`;

        console.log("更新后的 summary:", summary);
      }

      // 更新到 localStorage
      localStorage.setItem(
        "selectedPositionKeywords",
        summary.replace(/\r\n/g, "\n")
      );
      localStorage

      if (jdsEntry) {
        // 替换keywords_zh字段
        jdsEntry.keywords_zh = summary.replace(/\r\n/g, "\n");

        // 开启一个事务以保存数据
        const transaction = db.transaction(["jds"], "readwrite");
        const objectStore = transaction.objectStore("jds");

        // 使用put方法更新条目
        const updateRequest = objectStore.put(jdsEntry);

        updateRequest.onsuccess = () => {
          console.log("IndexedDB updated successfully.");
        };

        updateRequest.onerror = (event) => {
          console.error("Error updating IndexedDB:", event.target.error);
          alert("Error updating IndexedDB");
        };

        console.log("Updated Entry:", jdsEntry);
      } else {
        console.log("Entry not found in IndexedDB.");
      }

      // 更新搜索策略部分
      if (1) {
        let allStrategy = await pullAllSession();

        // 如果返回值是空字符串，则直接认为保存成功
        if (allStrategy === "") {
          saveButton.textContent = "保存成功";
          saveButton.style.background = "green";
          return;
        }

        // 如果allStrategy是数组，则将整个数组作为一个字段存入jds_Strategy
        if (Array.isArray(allStrategy)) {
          const db = await openIndexedDB();
          const selectedPosition = localStorage.getItem("selectedPosition");
          // 将整个数组作为对象的一个属性存入
          const dataToStore = {
            jds_id: selectedPosition,
            strategies: allStrategy // 这里是您要存储的数组数据
          };
          await storeDataInIndexedDB(db, "jds_Strategy", [dataToStore]);
          // 注意：storeDataInIndexedDB如果原本是批量存储的函数，请确保它能处理传入的数组（此处传入一个包含单个对象的数组）
        }

        populateStrategyDropdownFromLocalStorage()
        alert("Refreshed");
      }
    } catch (error) {
      console.log("Error:", error);
    } finally {
      refreshCurrentButton.disabled = false;
      refreshCurrentButton.textContent = "更新此岗位信息";
      isRefreshing = false;
    }
  });

