//智联保存策略发送消息的逻辑
document.addEventListener("DOMContentLoaded", async () => {
  const zhilianSaveBtn = document.getElementById("ZhiLianSaveSession");
  if (!zhilianSaveBtn) return;

  zhilianSaveBtn.addEventListener("click", async () => {
    zhilianSaveBtn.disabled = true;
    zhilianSaveBtn.textContent = "处理中...";
    zhilianSaveBtn.style.background = "grey";

    try {
      const tabs = await chrome.tabs.query({ active: true, currentWindow: true });
      if (!tabs || !tabs[0]) {
        throw new Error("未找到活动标签页");
      }

      const currentUrl = tabs[0].url;

      // 只处理智联页面
      if (!currentUrl.includes("zhaopin.com")) {
        throw new Error("当前页面不是智联，请在智联页面使用此功能");
      }

      console.log("发送 getSessionDataAndRemarkZhaopin 消息到 content.js");

      // 发送消息给 content.js
      chrome.tabs.sendMessage(
        tabs[0].id,
        { action: "getSessionDataAndRemarkZhaopin" },
        async (response) => {
          if (chrome.runtime.lastError) {
            console.error("Error:", chrome.runtime.lastError.message);
            if (chrome.runtime.lastError.message.includes("Could not establish connection")) {
              zhilianSaveBtn.textContent = "请刷新页面";
            } else {
              zhilianSaveBtn.textContent = "发送失败";
            }
            zhilianSaveBtn.style.background = "red";
            zhilianSaveBtn.disabled = false;
            return;
          }

          if (!response) {
            console.log("未能提取到Session数据");
            zhilianSaveBtn.textContent = "获取数据失败";
            zhilianSaveBtn.style.background = "red";
            zhilianSaveBtn.disabled = false;
            return;
          }

          try {
            // 处理返回体
            let scrapeData = response;
            let localSession = response.sessionData;

            console.log("获取到的Session数据:", localSession);
            console.log("获取到的scrapeData:", scrapeData);

            // 获取 position_id
            const positionId = localStorage.getItem("selectedPosition");
            if (!positionId || !localSession) {
              throw new Error("Missing required parameters: position_id or strategy");
            }

            // ========== 查重逻辑 ==========
            const params = new URLSearchParams({
              position_id: positionId,
              strategy: localSession
            });

            let isDuplicate = false;

            await fetch("https://talent.example.invalid/api/duplicate_search_strategy.php", {
              method: "POST",
              headers: {
                "Content-Type": "application/x-www-form-urlencoded"
              },
              body: params.toString()
            })
              .then(res => res.json())
              .then(data => {
                if (data.duplicate === "yes") {
                  isDuplicate = true;
                  console.log("Duplicate found:", data);
                  return Promise.reject("Duplicate found");
                }
                if (data.success) {
                  console.log("Duplicate search completed:", data);
                } else {
                  console.error("Duplicate search failed:", data.message);
                }
              })
              .catch(error => {
                if (error === "Duplicate found") {
                  return;
                }
                console.error("Error during duplicate search:", error);
              });

            // ========== 如果不是重复，发送到API ==========
            if (!isDuplicate) {
              const formData = new FormData();
              formData.append("chatbotID", "__TALENTMATCH_MODEL_14__");
              formData.append("userID", "__TALENTMATCH_USER_01__");
              formData.append("prompt", localSession);
              formData.append("permission", "1");

              const apiResponse = await fetch(
                "https://model.example.invalid/api/completions/quora.php",
                {
                  method: "POST",
                  body: formData
                }
              );

              const apiData = await apiResponse.json();
              const content = apiData.choices?.[0]?.message?.content;

              if (!content) {
                throw new Error("没有找到返回的内容");
              }

              console.log("返回的内容:", content);

              // ========== 保存策略到数据库 ==========
              const positionID = localStorage.getItem("selectedPosition");
              const strategyFormData = new FormData();
              strategyFormData.append("position_id", positionID);
              strategyFormData.append(
                "name",
                scrapeData.headhunterName +
                " " +
                scrapeData.numberCount +
                content
              );
              strategyFormData.append("strategy", localSession);
              strategyFormData.append("source", "zhilian");

              await fetch("https://talent.example.invalid/api/add_search_strategy.php", {
                method: "POST",
                body: strategyFormData
              });

              zhilianSaveBtn.textContent = "保存成功";
              zhilianSaveBtn.style.background = "green";
            } else {
              zhilianSaveBtn.textContent = "Session重复";
              zhilianSaveBtn.style.background = "orange";
            }

          } catch (error) {
            console.error("处理失败:", error);
            zhilianSaveBtn.textContent = "保存失败";
            zhilianSaveBtn.style.background = "red";
          } finally {
            zhilianSaveBtn.disabled = false;
          }
        }
      );

    } catch (error) {
      console.error("智联保存策略错误:", error);
      zhilianSaveBtn.textContent = "出错了";
      zhilianSaveBtn.style.background = "red";
      zhilianSaveBtn.disabled = false;
    }
  });
});
